import{_ as a,H as e,f as t,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"40 | 谈谈Jetty性能调优的思路","description":"","frontmatter":{},"headers":[{"level":2,"title":"操作系统层面调优","slug":"操作系统层面调优","link":"#操作系统层面调优","children":[]},{"level":2,"title":"Jetty本身的调优","slug":"jetty本身的调优","link":"#jetty本身的调优","children":[]},{"level":2,"title":"Jetty性能测试","slug":"jetty性能测试","link":"#jetty性能测试","children":[]},{"level":2,"title":"本期精华","slug":"本期精华","link":"#本期精华","children":[]},{"level":2,"title":"课后思考","slug":"课后思考","link":"#课后思考","children":[]}],"relativePath":"深入拆解Tomcat&Jetty/40-谈谈Jetty性能调优的思路.md","filePath":"深入拆解Tomcat&Jetty/40-谈谈Jetty性能调优的思路.md","lastUpdated":1779821049000}'),p={name:"深入拆解Tomcat&Jetty/40-谈谈Jetty性能调优的思路.md"};function l(i,s,c,o,r,d){return e(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="_40-谈谈jetty性能调优的思路" tabindex="-1">40 | 谈谈Jetty性能调优的思路 <a class="header-anchor" href="#_40-谈谈jetty性能调优的思路" aria-label="Permalink to &quot;40 | 谈谈Jetty性能调优的思路&quot;">​</a></h1><p>关于Tomcat的性能调优，前面我主要谈了工作经常会遇到的有关JVM GC、监控、I/O和线程池以及CPU的问题定位和调优，今天我们来看看Jetty有哪些调优的思路。</p><p>关于Jetty的性能调优，官网上给出了一些很好的建议，分为操作系统层面和Jetty本身的调优，我们将分别来看一看它们具体是怎么做的，最后再通过一个实战案例来学习一下如何确定Jetty的最佳线程数。</p><h2 id="操作系统层面调优" tabindex="-1">操作系统层面调优 <a class="header-anchor" href="#操作系统层面调优" aria-label="Permalink to &quot;操作系统层面调优&quot;">​</a></h2><p>对于Linux操作系统调优来说，我们需要加大一些默认的限制值，这些参数主要可以在 <code>/etc/security/limits.conf</code> 中或通过 <code>sysctl</code> 命令进行配置，其实这些配置对于Tomcat来说也是适用的，下面我来详细介绍一下这些参数。</p><p><strong>TCP缓冲区大小</strong></p><p>TCP的发送和接收缓冲区最好加大到16MB，可以通过下面的命令配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> sysctl -w net.core.rmem_max = 16777216</span></span>
<span class="line"><span> sysctl -w net.core.wmem_max = 16777216</span></span>
<span class="line"><span> sysctl -w net.ipv4.tcp_rmem =“4096 87380 16777216”</span></span>
<span class="line"><span> sysctl -w net.ipv4.tcp_wmem =“4096 16384 16777216”</span></span></code></pre></div><p><strong>TCP队列大小</strong></p><p><code>net.core.somaxconn</code> 控制TCP连接队列的大小，默认值为128，在高并发情况下明显不够用，会出现拒绝连接的错误。但是这个值也不能调得过高，因为过多积压的TCP连接会消耗服务端的资源，并且会造成请求处理的延迟，给用户带来不好的体验。因此我建议适当调大，推荐设置为4096。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> sysctl -w net.core.somaxconn = 4096</span></span></code></pre></div><p><code>net.core.netdev_max_backlog</code> 用来控制Java程序传入数据包队列的大小，可以适当调大。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl -w net.core.netdev_max_backlog = 16384</span></span>
<span class="line"><span>sysctl -w net.ipv4.tcp_max_syn_backlog = 8192</span></span>
<span class="line"><span>sysctl -w net.ipv4.tcp_syncookies = 1</span></span></code></pre></div><p><strong>端口</strong></p><p>如果Web应用程序作为客户端向远程服务器建立了很多TCP连接，可能会出现TCP端口不足的情况。因此最好增加使用的端口范围，并允许在TIME_WAIT中重用套接字：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl -w net.ipv4.ip_local_port_range =“1024 65535”</span></span>
<span class="line"><span>sysctl -w net.ipv4.tcp_tw_recycle = 1</span></span></code></pre></div><p><strong>文件句柄数</strong></p><p>高负载服务器的文件句柄数很容易耗尽，这是因为系统默认值通常比较低，我们可以在 <code>/etc/security/limits.conf</code> 中为特定用户增加文件句柄数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户名 hard nofile 40000</span></span>
<span class="line"><span>用户名 soft nofile 40000</span></span></code></pre></div><p><strong>拥塞控制</strong></p><p>Linux内核支持可插拔的拥塞控制算法，如果要获取内核可用的拥塞控制算法列表，可以通过下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl net.ipv4.tcp_available_congestion_control</span></span></code></pre></div><p>这里我推荐将拥塞控制算法设置为cubic：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl -w net.ipv4.tcp_congestion_control = cubic</span></span></code></pre></div><h2 id="jetty本身的调优" tabindex="-1">Jetty本身的调优 <a class="header-anchor" href="#jetty本身的调优" aria-label="Permalink to &quot;Jetty本身的调优&quot;">​</a></h2><p>Jetty本身的调优，主要是设置不同类型的线程的数量，包括Acceptor和Thread Pool。</p><p><strong>Acceptors</strong></p><p>Acceptor的个数accepts应该设置为大于等于1，并且小于等于CPU核数。</p><p><strong>Thread Pool</strong></p><p>限制Jetty的任务队列非常重要。默认情况下，队列是无限的！因此，如果在高负载下超过Web应用的处理能力，Jetty将在队列上积压大量待处理的请求。并且即使负载高峰过去了，Jetty也不能正常响应新的请求，这是因为仍然有很多请求在队列等着被处理。</p><p>因此对于一个高可靠性的系统，我们应该通过使用有界队列立即拒绝过多的请求（也叫快速失败）。那队列的长度设置成多大呢，应该根据Web应用的处理速度而定。比如，如果Web应用每秒可以处理100个请求，当负载高峰到来，我们允许一个请求可以在队列积压60秒，那么我们就可以把队列长度设置为60 × 100 = 6000。如果设置得太低，Jetty将很快拒绝请求，无法处理正常的高峰负载，以下是配置示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;Configure id=&quot;Server&quot; class=&quot;org.eclipse.jetty.server.Server&quot;&gt;</span></span>
<span class="line"><span>    &lt;Set name=&quot;ThreadPool&quot;&gt;</span></span>
<span class="line"><span>      &lt;New class=&quot;org.eclipse.jetty.util.thread.QueuedThreadPool&quot;&gt;</span></span>
<span class="line"><span>        &lt;!-- specify a bounded queue --&gt;</span></span>
<span class="line"><span>        &lt;Arg&gt;</span></span>
<span class="line"><span>           &lt;New class=&quot;java.util.concurrent.ArrayBlockingQueue&quot;&gt;</span></span>
<span class="line"><span>              &lt;​Arg type=&quot;int&quot;&gt;6000&lt;​/Arg&gt;</span></span>
<span class="line"><span>           &lt;/New&gt;</span></span>
<span class="line"><span>      &lt;/Arg&gt;</span></span>
<span class="line"><span>        &lt;​Set name=&quot;minThreads&quot;&gt;10&lt;​/Set&gt;</span></span>
<span class="line"><span>        &lt;​Set name=&quot;maxThreads&quot;&gt;200&lt;​/Set&gt;</span></span>
<span class="line"><span>        &lt;​Set name=&quot;detailedDump&quot;&gt;false&lt;​/Set&gt;</span></span>
<span class="line"><span>      &lt;/New&gt;</span></span>
<span class="line"><span>    &lt;/Set&gt;</span></span>
<span class="line"><span>&lt;/Configure&gt;</span></span></code></pre></div><p>那如何配置Jetty的线程池中的线程数呢？跟Tomcat一样，你可以根据实际压测，如果I/O越密集，线程阻塞越严重，那么线程数就可以配置多一些。通常情况，增加线程数需要更多的内存，因此内存的最大值也要跟着调整，所以一般来说，Jetty的最大线程数应该在50到500之间。</p><h2 id="jetty性能测试" tabindex="-1">Jetty性能测试 <a class="header-anchor" href="#jetty性能测试" aria-label="Permalink to &quot;Jetty性能测试&quot;">​</a></h2><p>接下来我们通过一个实验来测试一下Jetty的性能。我们可以在 <a href="https://repo1.maven.org/maven2/org/eclipse/jetty/aggregate/jetty-all/9.4.19.v20190610/jetty-all-9.4.19.v20190610-uber.jar" target="_blank" rel="noreferrer">这里</a> 下载Jetty的JAR包。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Tomcat%26Jetty/images/117877/2d78b4d2b8eca5912ed5899aa57b73c9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Tomcat%26Jetty/images/117877/2d78b4d2b8eca5912ed5899aa57b73c9.png" alt=""></a></p><p>第二步我们创建一个Handler，这个Handler用来向客户端返回“Hello World”，并实现一个main方法，根据传入的参数创建相应数量的线程池。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class HelloWorld extends AbstractHandler {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public void handle(String target, Request baseRequest, HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {</span></span>
<span class="line"><span>        response.setContentType(&quot;text/html; charset=utf-8&quot;);</span></span>
<span class="line"><span>        response.setStatus(HttpServletResponse.SC_OK);</span></span>
<span class="line"><span>        response.getWriter().println(&quot;&lt;​h1&gt;Hello World&lt;​/h1&gt;&quot;);</span></span>
<span class="line"><span>        baseRequest.setHandled(true);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static void main(String[] args) throws Exception {</span></span>
<span class="line"><span>        //根据传入的参数控制线程池中最大线程数的大小</span></span>
<span class="line"><span>        int maxThreads = Integer.parseInt(args[0]);</span></span>
<span class="line"><span>        System.out.println(&quot;maxThreads:&quot; + maxThreads);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        //创建线程池</span></span>
<span class="line"><span>        QueuedThreadPool threadPool = new QueuedThreadPool();</span></span>
<span class="line"><span>        threadPool.setMaxThreads(maxThreads);</span></span>
<span class="line"><span>        Server server = new Server(threadPool);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        ServerConnector http = new ServerConnector(server,</span></span>
<span class="line"><span>                new HttpConnectionFactory(new HttpConfiguration()));</span></span>
<span class="line"><span>        http.setPort(8000);</span></span>
<span class="line"><span>        server.addConnector(http);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        server.start();</span></span>
<span class="line"><span>        server.join();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>第三步，我们编译这个Handler，得到HelloWorld.class。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>javac -cp jetty.jar HelloWorld.java</span></span></code></pre></div><p>第四步，启动Jetty server，并且指定最大线程数为4。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>java -cp .:jetty.jar HelloWorld 4</span></span></code></pre></div><p>第五步，启动压测工具Apache Bench。关于Apache Bench的使用，你可以参考 <a href="https://httpd.apache.org/docs/current/programs/ab.html" target="_blank" rel="noreferrer">这里</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ab -n 200000 -c 100 http://localhost:8000/</span></span></code></pre></div><p>上面命令的意思是向Jetty server发出20万个请求，开启100个线程同时发送。</p><p>经过多次压测，测试结果稳定以后，在Linux 4核机器上得到的结果是这样的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Tomcat%26Jetty/images/117877/33b63aca5bc1e92864c01d1b5c11f804.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Tomcat%26Jetty/images/117877/33b63aca5bc1e92864c01d1b5c11f804.png" alt=""></a></p><p>从上面的测试结果我们可以看到，20万个请求在9.99秒内处理完成，RPS达到了20020。 不知道你是否好奇，为什么我把最大线程数设置为4呢？是不是有点小？</p><p>别着急，接下来我们就试着逐步加大最大线程数，直到找到最佳值。下面这个表格显示了在其他条件不变的情况下，只调整线程数对RPS的影响。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Tomcat%26Jetty/images/117877/782ab4f927e8e27b762f7fcb48c48cdb.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3Tomcat%26Jetty/images/117877/782ab4f927e8e27b762f7fcb48c48cdb.jpg" alt=""></a></p><p>我们发现一个有意思的现象，线程数从4增加到6，RPS确实增加了。但是线程数从6开始继续增加，RPS不但没有跟着上升，反而下降了，而且线程数越多，RPS越低。</p><p>发生这个现象的原因是，测试机器的CPU只有4核，而我们测试的程序做得事情比较简单，没有I/O阻塞，属于CPU密集型程序。对于这种程序，最大线程数可以设置为比CPU核心稍微大一点点。那具体设置成多少是最佳值呢，我们需要根据实验里的步骤反复测试。你可以看到在我们这个实验中，当最大线程数为6，也就CPU核数的1.5倍时，性能达到最佳。</p><h2 id="本期精华" tabindex="-1">本期精华 <a class="header-anchor" href="#本期精华" aria-label="Permalink to &quot;本期精华&quot;">​</a></h2><p>今天我们首先学习了Jetty调优的基本思路，主要分为操作系统级别的调优和Jetty本身的调优，其中操作系统级别也适用于Tomcat。接着我们通过一个实例来寻找Jetty的最佳线程数，在测试中我们发现，对于CPU密集型应用，将最大线程数设置CPU核数的1.5倍是最佳的。因此，在我们的实际工作中，切勿将线程池直接设置得很大，因为程序所需要的线程数可能会比我们想象的要小。</p><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">​</a></h2><p>我在今天文章前面提到，Jetty的最大线程数应该在50到500之间。但是我们的实验中测试发现，最大线程数为6时最佳，这是不是矛盾了？</p><p>不知道今天的内容你消化得如何？如果还有疑问，请大胆的在留言区提问，也欢迎你把你的课后思考和心得记录下来，与我和其他同学一起讨论。如果你觉得今天有所收获，欢迎你把它分享给你的朋友。</p>`,57)])])}const u=a(p,[["render",l]]);export{g as __pageData,u as default};
